/**
 * Occasion Flat-Lay Orchestration Service
 * Orchestrates AI curation + flat-lay image generation for occasion presets
 */

import type { OccasionFlatLayRequest, OccasionFlatLayResponse, FlatLayItem } from '../types/image-types';
import { buildOccasionFlatLaySystemPrompt, getOccasionPresetConfig } from '../prompts/occasion-flat-lay-prompt';
import { computeFlatLayLayout } from '../prompts/image-prompts';
import { OpenRouterImageClient } from './image-generation-service';

const LOG_PREFIX = '[OccasionFlatLay]';
const MIN_CURATED_ITEMS = 3;

/**
 * OpenRouter chat completion configuration for AI curation
 * Uses a text model (not image generation model) for outfit curation
 */
const CURATION_CONFIG = {
  baseUrl: 'https://openrouter.ai/api/v1',
  model: 'google/gemini-3-flash-preview',  // Text model for curation (same as ai-chat-service)
  timeout: 30000,
  maxTokens: 2048,
};

/**
 * Parse AI response to extract curated items and image prompt
 */
export function parseAIResponse(responseText: string): {
  curatedItems: FlatLayItem[];
  imagePrompt: string | null;
} {
  const curatedItems: FlatLayItem[] = [];
  let imagePrompt: string | null = null;

  // Extract CURATED_ITEMS section
  const itemsMatch = responseText.match(/CURATED_ITEMS:\s*\n([\s\S]*?)(?=IMAGE_PROMPT:|$)/i);
  if (itemsMatch) {
    const itemLines = itemsMatch[1].trim().split('\n').filter(line => line.trim());
    for (const line of itemLines) {
      // Parse: "1. Item Name | Category | Color | Visual Description"
      const match = line.match(/^\d+\.\s*(.+?)\s*\|\s*(.+?)\s*\|\s*(.+?)\s*\|\s*(.+)$/);
      if (match) {
        curatedItems.push({
          name: match[1].trim(),
          category: match[2].trim(),
          color: match[3].trim(),
          visualDescription: match[4].trim(),
        });
      }
    }
  }

  // Deduplicate by category — keep first item per category (spec: no duplicate outfit items)
  const seenCategories = new Set<string>();
  const deduplicatedItems: FlatLayItem[] = [];
  for (const item of curatedItems) {
    const categoryKey = item.category.toLowerCase();
    if (!seenCategories.has(categoryKey)) {
      seenCategories.add(categoryKey);
      deduplicatedItems.push(item);
    }
  }

  // Extract IMAGE_PROMPT section
  const promptMatch = responseText.match(/IMAGE_PROMPT:\s*\n([\s\S]*?)$/i);
  if (promptMatch) {
    imagePrompt = promptMatch[1].trim();
  }

  return { curatedItems: deduplicatedItems, imagePrompt };
}

/**
 * Build a structured image generation prompt from parsed curated items.
 * Uses spatial layout positioning to ensure every curated item is explicitly
 * placed in the image with clear positional context for the image model.
 */
export function buildImagePromptFromItems(
  curatedItems: FlatLayItem[],
  occasionLabel: string
): string {
  const count = curatedItems.length;
  const layout = computeFlatLayLayout(curatedItems);

  // Determine layout pattern label
  let layoutPattern: string;
  if (count <= 3) layoutPattern = 'inverted triangle arrangement';
  else if (count === 4) layoutPattern = '2\u00D72 grid';
  else if (count === 5) layoutPattern = 'cross/diamond arrangement';
  else layoutPattern = '2\u00D73 grid';

  // Build item lines with spatial positions
  const itemLines = layout.map((entry) => {
    const colorInfo = entry.item.color ? `${entry.item.color.toLowerCase()} ` : '';
    return `- ${entry.position} (${entry.sizeHint}): a ${colorInfo}${entry.item.name.toLowerCase()} (${entry.item.category.toLowerCase()}), ${entry.presentationHint}`;
  }).join('\n');

  return `Generate a professional overhead flat-lay photograph with NO text, labels, watermarks, or written words of any kind. The image shows exactly ${count} fashion items arranged on a pristine white surface as a coordinated ${occasionLabel.toLowerCase()} outfit. The layout is a balanced ${layoutPattern}:\n${itemLines}\nEach item is clearly separated with generous spacing between pieces. All ${count} items are fully visible with no overlap or cropping. Photographed from directly overhead with soft, diffused studio lighting. Professional e-commerce product photography quality. Square 1:1 format.`;
}

/**
 * Call OpenRouter chat completion for AI outfit curation
 */
async function callAICuration(
  systemPrompt: string,
  apiKey: string
): Promise<string> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), CURATION_CONFIG.timeout);

  try {
    const response = await fetch(`${CURATION_CONFIG.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
        'HTTP-Referer': 'https://ootday.com',
        'X-Title': 'OOTDay Fashion Assistant',
      },
      body: JSON.stringify({
        model: CURATION_CONFIG.model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: 'Please curate an outfit for me based on the occasion and my profile, then generate the flat-lay image prompt.' },
        ],
        max_tokens: CURATION_CONFIG.maxTokens,
      }),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(
        `OpenRouter API error: ${response.status} - ${(errorData as any).error?.message || response.statusText}`
      );
    }

    const data = await response.json();
    const content = (data as any).choices?.[0]?.message?.content;

    if (!content || typeof content !== 'string') {
      throw new Error('Empty or invalid response from AI curation');
    }

    return content;
  } catch (error) {
    clearTimeout(timeoutId);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('AI curation request timed out');
    }
    throw error;
  }
}

/**
 * Main orchestration function: AI curation -> image prompt extraction -> image generation
 */
export async function generateOccasionFlatLay(
  request: OccasionFlatLayRequest,
  apiKey: string
): Promise<OccasionFlatLayResponse> {
  console.log(`${LOG_PREFIX} Starting generation for occasion: ${request.occasion}`);

  try {
    // Step 1: Build system prompt
    const systemPrompt = buildOccasionFlatLaySystemPrompt(request);
    console.log(`${LOG_PREFIX} System prompt built (${systemPrompt.length} chars)`);

    // Step 2: Call AI for outfit curation + image prompt
    console.log(`${LOG_PREFIX} Calling AI curation...`);
    const aiResponse = await callAICuration(systemPrompt, apiKey);
    console.log(`${LOG_PREFIX} AI curation response received (${aiResponse.length} chars)`);

    // Step 3: Parse AI response
    const { curatedItems, imagePrompt } = parseAIResponse(aiResponse);
    console.log(`${LOG_PREFIX} Parsed ${curatedItems.length} curated items`);

    if (!imagePrompt) {
      console.error(`${LOG_PREFIX} No image prompt found in AI response`);
      return {
        success: false,
        curatedItems,
        error: 'AI_PARSE_ERROR',
        message: 'Could not extract image prompt from AI response',
      };
    }

    if (curatedItems.length < MIN_CURATED_ITEMS) {
      console.error(`${LOG_PREFIX} Insufficient curated items: ${curatedItems.length} (minimum ${MIN_CURATED_ITEMS})`);
      return {
        success: false,
        curatedItems,
        imagePrompt,
        error: 'INSUFFICIENT_ITEMS',
        message: `AI returned ${curatedItems.length} items, but a complete look requires at least ${MIN_CURATED_ITEMS}`,
      };
    }

    console.log(`${LOG_PREFIX} AI image prompt extracted (${imagePrompt.length} chars)`);

    // Step 4: Build a structured image prompt from parsed items (not the AI's free-text)
    // Image models often drop items when described loosely in a paragraph.
    // By constructing the prompt from the structured curatedItems array with explicit
    // count reinforcement, every item is guaranteed to be listed for the image model.
    const config = getOccasionPresetConfig(request.occasion);
    const structuredImagePrompt = buildImagePromptFromItems(curatedItems, config.label);
    console.log(`${LOG_PREFIX} Structured image prompt built (${structuredImagePrompt.length} chars, ${curatedItems.length} items)`);

    console.log(`${LOG_PREFIX} Generating flat-lay image...`);
    const imageClient = new OpenRouterImageClient(apiKey);
    const imageResult = await imageClient.generateRawFlatLay(structuredImagePrompt);

    if (!imageResult.success) {
      console.error(`${LOG_PREFIX} Image generation failed:`, imageResult.error);
      return {
        success: false,
        curatedItems,
        imagePrompt: structuredImagePrompt,
        error: imageResult.error || 'IMAGE_GENERATION_FAILED',
        message: imageResult.message || 'Failed to generate flat-lay image',
      };
    }

    console.log(`${LOG_PREFIX} Flat-lay image generated successfully`);

    return {
      success: true,
      imageBase64: imageResult.imageBase64,
      imageUrl: imageResult.imageUrl,
      curatedItems,
      imagePrompt: structuredImagePrompt,
      message: 'Occasion flat-lay generated successfully',
    };
  } catch (error) {
    console.error(`${LOG_PREFIX} Error:`, error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return {
      success: false,
      error: 'GENERATION_ERROR',
      message: `Failed to generate occasion flat-lay: ${errorMessage}`,
    };
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { ChatHeader, ChatStatus } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit, FlatLayItem, Product } from '@/lib/types'
import {
  findReplacementsForInconsistentProducts,
  validateProductVisualConsistency,
} from '@/lib/utils/product-visual-validator'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v8.0: All products for visual consistency replacement lookup
  const [allProducts, setAllProducts] = useState<Product[]>([])

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  /**
   * v8.0: Apply product replacements to an outfit for visual consistency
   * Creates a new outfit with items array where mismatched items are replaced
   * Recalculates totalPrice based on replacement prices
   */
  const applyProductReplacements = useCallback((
    outfit: Outfit,
    replacements: Map<string, Product>
  ): Outfit => {
    if (replacements.size === 0) return outfit

    const updatedItems = outfit.items.map(item => {
      const replacement = replacements.get(item.sku)
      return replacement || item
    })

    // Recalculate total price
    const newTotalPrice = updatedItems.reduce((sum, item) => sum + (item.price || 0), 0)

    return {
      ...outfit,
      items: updatedItems,
      totalPrice: newTotalPrice,
    }
  }, [])

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  // v9.0: Clear chat handler for enhanced header
  const handleClearChat = useCallback(() => {
    // Reset to initial greeting
    const greeting: ChatMessageType = {
      id: 'greeting-initial',
      content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
      sender: 'assistant',
      timestamp: new Date(),
    }
    setMessages([greeting])
    // Reset session context
    setSessionContext(createSessionContext())
  }, [])

  // v9.0: Compute chat status based on current state
  const getChatStatus = useCallback((): ChatStatus => {
    if (isTyping) return 'typing'
    if (generatingImage) return 'generating'
    return 'online'
  }, [isTyping, generatingImage])

  /**
   * v5.0: Generate flat-lay image for an outfit and update the message
   * v8.0: Enhanced with visual consistency validation and product replacement
   *
   * This function:
   * 1. Validates visual consistency between product text and thumbnails
   * 2. Replaces visually inconsistent products with consistent alternatives
   * 3. Generates flat-lay image using the corrected products
   * 4. Updates both the flat-lay image AND the product list in the message
   */
  const generateFlatLayForOutfit = useCallback(async (
    outfit: Outfit,
    messageId: string,
    productCatalog?: Product[]
  ) => {
    console.log(`[Chat] Generating flat-lay for outfit ${outfit.id}...`)

    // v8.0: Check for visual inconsistencies and find replacements if catalog provided
    let effectiveOutfit = outfit
    let replacementsMade = new Map<string, Product>()

    if (productCatalog && productCatalog.length > 0) {
      const replacementResult = findReplacementsForInconsistentProducts(
        outfit.items,
        productCatalog,
        { targetGender: 'women' }
      )

      if (replacementResult.replacements.size > 0) {
        console.log(
          `[Chat] Replacing ${replacementResult.replacements.size} visually inconsistent products in outfit ${outfit.id}:`,
          Array.from(replacementResult.replacements.entries()).map(([origSku, replacement]) => ({
            original: origSku,
            replacement: replacement.sku,
            name: replacement.name,
          }))
        )

        // Apply replacements to create the effective outfit
        effectiveOutfit = applyProductReplacements(outfit, replacementResult.replacements)
        replacementsMade = replacementResult.replacements

        // Update the message with corrected product list BEFORE generating flat-lay
        // This ensures the product thumbnails shown match the flat-lay image
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }

      if (replacementResult.unreplaceableSkus.length > 0) {
        console.warn(
          `[Chat] ${replacementResult.unreplaceableSkus.length} items in outfit ${outfit.id} have visual mismatches but no replacement found:`,
          replacementResult.unreplaceableSkus
        )
      }
    }

    // Extract FlatLayItem array from effective outfit items (with replacements applied)
    const flatLayItems: FlatLayItem[] = effectiveOutfit.items.slice(0, 5).map((item: Product) => ({
      name: item.name,
      category: item.subCategory || item.category || 'Item',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
    }))
    const occasionContext = outfit.description

    if (flatLayItems.length === 0) {
      console.log('[Chat] No items to generate flat-lay for')
      return
    }

    try {
      const imageResponse = await fetch('/api/generate-image', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          description: outfit.description || 'LOOKs Inspiration',
          generationType: 'flat-lay',
          flatLayItems,
          occasionContext,
        }),
      })

      const imageData = await imageResponse.json()

      if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
        console.log(`[Chat] Flat-lay generated successfully for outfit ${outfit.id}`)

        // Update the message's outfit with the flat-lay image
        // Note: Product items were already updated above if replacements were made
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        flatLayImageUrl: imageData.imageUrl,
                        flatLayImageBase64: imageData.imageBase64,
                        isGeneratingFlatLay: false,
                        // Ensure items are the effective items (with replacements)
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      } else {
        console.error('[Chat] Flat-lay generation failed:', imageData.message)
        // Mark as not generating (will show fallback thumbnail)
        // Still apply any product replacements even if image generation failed
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        isGeneratingFlatLay: false,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }
    } catch (error) {
      console.error('[Chat] Flat-lay generation error:', error)
      // Mark as not generating on error
      // Still apply any product replacements even if image generation failed
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg.id === messageId && msg.outfits) {
            return {
              ...msg,
              outfits: msg.outfits.map((o) =>
                o.id === outfit.id
                  ? {
                      ...o,
                      isGeneratingFlatLay: false,
                      items: effectiveOutfit.items,
                      totalPrice: effectiveOutfit.totalPrice,
                    }
                  : o
              ),
            }
          }
          return msg
        })
      )
    }
  }, [applyProductReplacements])

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // v8.0: Collect all products from outfits for visual consistency replacement lookup
      const outfitProducts: Product[] = (data.outfits || []).flatMap((o: Outfit) => o.items || [])
      if (outfitProducts.length > 0) {
        setAllProducts(prev => {
          // Merge with existing products, avoiding duplicates by SKU
          const existingSkus = new Set(prev.map(p => p.sku))
          const newProducts = outfitProducts.filter((p: Product) => !existingSkus.has(p.sku))
          return [...prev, ...newProducts]
        })
      }

      // v5.0: Mark outfits as generating flat-lay if we have image request
      const outfitsWithLoading = (data.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: data.imageRequest && outfit.items.length > 0,
      }))

      // Create AI response message
      const messageId = `ai-${Date.now()}`
      const aiResponse: ChatMessageType = {
        id: messageId,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: outfitsWithLoading,
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v5.0: Generate flat-lay images for each outfit (embedded in card, no separate message)
      if (data.imageRequest && outfitsWithLoading.length > 0) {
        console.log('[Chat] Image request detected, generating flat-lay for outfit cards...')

        // Add AI acknowledgment message for generation
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        // Generate flat-lay for each outfit, passing allProducts for visual consistency replacement
        for (const outfit of outfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      const messageId = `ai-mock-${Date.now()}`

      // v5.0: Mark mock outfits as generating flat-lay
      const mockOutfitsWithLoading = (aiResponse.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: outfit.items.length > 0,
      }))

      const mockMessage: ChatMessageType = {
        ...aiResponse,
        id: messageId,
        outfits: mockOutfitsWithLoading,
      }

      setMessages((prev) => [...prev, mockMessage])
      setIsTyping(false)

      // v5.0: Auto-generate flat-lay for mock responses
      if (mockOutfitsWithLoading.length > 0) {
        console.log('[Chat] Fallback: Auto-generating flat-lay for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        for (const outfit of mockOutfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
