      filteredProducts,
      sessionContext,
      3 // Minimum 3 products for outfit recommendations
    )

    // If insufficient unique products, return helpful message
    if (!sufficient) {
      return {
        message: insufficientMessage || 'ขออภัยค่ะ ไม่พบสินค้าใหม่เพิ่มเติมในหมวดนี้',
        recommendedProducts: [],
        sessionContext,
      }
    }

    // Use unique products for recommendations
    filteredProducts = uniqueProducts

    // If no products available after filtering, return error
    if (filteredProducts.length === 0) {
      return {
        message:
          'ขออภัยค่ะ ไม่พบสินค้าที่ตรงกับความต้องการของคุณในขณะนี้ คุณลองปรับเกณฑ์การค้นหาหรือถามคำถามใหม่ได้ค่ะ',
        recommendedProducts: [],
        sessionContext,
      }
    }

    // Rank products by relevance so truncation keeps the best candidates
    const legacyBudget = request.userPreferences?.budget || extractBudget(request.message)
    filteredProducts = rankProductsByRelevance(filteredProducts, occasion, legacyBudget)
    console.log(`[AI Chat] Ranked ${filteredProducts.length} products by relevance`)

    // v2.1: CRITICAL - Detect category to determine template type (A or B)
    const categoryDetection = detectCategory(request.message)
    console.log(formatCategoryDetection(categoryDetection))

    // v3.0: RAG-based knowledge retrieval with fallback to keyword-based
    // Uses semantic search to find relevant fashion knowledge
    const ragResult = await retrieveKnowledgeWithRAG(
      request.message,
      userQuery.detectedGender || sessionContext.conversationContext.gender,
      userQuery.detectedOccasion || sessionContext.conversationContext.occasion
    )
    const knowledgeContext = ragResult.knowledgeContext

    // Update session with retrieved knowledge IDs (for caching and tracking)
    if (ragResult.retrievedIds.length > 0) {
      sessionContext = {
        ...sessionContext,
        retrievedKnowledgeIds: [
          ...(sessionContext.retrievedKnowledgeIds || []),
          ...ragResult.retrievedIds.filter(
            (id) => !(sessionContext.retrievedKnowledgeIds || []).includes(id)
          ),
        ],
      }
    }

    // Log retrieval method used
    if (!ragResult.usedFallback) {
      console.log(`[AI Chat] 📚 Knowledge Base: RAG retrieved ${ragResult.retrievedIds.length} documents`)
    } else if (knowledgeContext) {
      console.log('[AI Chat] 📚 Knowledge Base: Using keyword-based fallback')
    }

    // Create AI prompt with product context
    const prompt = createOutfitPrompt(
      occasion || 'general occasion',
      filteredProducts.slice(0, 20), // Limit to top 20 to save tokens
      request.userPreferences
    )

    // v2.5: Add ENHANCED user preferences context (Name, Age, Style, Gender)
    const prefs = request.userPreferences;
    let userPreferencesContext = '';

    if (prefs) {
      const parts = [];
      if (prefs.userName) parts.push(`Name: ${prefs.userName}`);
      if (prefs.gender) parts.push(`Gender: ${prefs.gender}`);
      if (prefs.ageRange) parts.push(`Age: ${prefs.ageRange}`);
      if (prefs.stylePreferences?.length) parts.push(`Style: ${prefs.stylePreferences.join(', ')}`);

      if (parts.length > 0) {
        userPreferencesContext = `[USER PROFILE]\n${parts.join('\n')}\n`;
      }
    }

    // v2.1: Inject template-specific instruction based on category
    const templateInstruction = getTemplateInstruction(categoryDetection.category)

    // v2.2: Generate follow-up instruction if in follow-up mode (Step 4)
    const followUpInstruction = generateFollowUpInstruction(followUpDetection);

    // Build enhanced prompt with template, knowledge context, user preferences, and follow-up instructions
    // v2.2: Add knowledge context for fashion expertise
    // v2.4: Add user preferences context for gender awareness
    let enhancedPrompt = `${userPreferencesContext}${templateInstruction}${knowledgeContext}\n\n${prompt}`

    if (followUpInstruction) {
      enhancedPrompt = `${followUpInstruction}\n\n${enhancedPrompt}`
      console.log('[AI Chat] 🔄 Step 4: Follow-up instruction injected into prompt');
    }

    // v2.1: CRITICAL - Determine if we should force recommendations
    // Force if:
    // 1. We've asked 2 clarifications already (shouldForceNow = true), OR
    // 2. User just answered a clarification (detect this from last assistant message), OR
    // 3. We're in follow-up phase (Step 4 - POST-RECOMMENDATION LOCKOUT)
    const lastAssistantMessage = request.conversationHistory?.filter(m => m.role === 'assistant').pop();
    const isAnsweringPreviousClarification = lastAssistantMessage &&
      sessionContext.askedClarifications.length > 0 &&
      isAnsweringClarification(request.message, sessionContext.askedClarifications[sessionContext.askedClarifications.length - 1]);

    // v2.2: Always force recommendations in follow-up phase (Step 4)
    const shouldInjectForceInstruction = shouldForceNow || isAnsweringPreviousClarification || isFollowUpPhase;

    if (shouldInjectForceInstruction) {
      if (isFollowUpPhase) {
        console.log('[AI Chat] 🔴 Step 4: POST-RECOMMENDATION LOCKOUT - Forcing recommendations (no questions allowed).');
      } else {
        console.log('[AI Chat] 🔴 Detected: User answered clarification OR hit limit. Forcing recommendations.');
      }
    }

    // Call AI with enhanced prompt (includes template instruction), session context, and force flag
    let aiResponse = await callOpenRouter(
      enhancedPrompt, // v2.1: Use enhanced prompt with template instruction
      request.conversationHistory,
      sessionContext,
      shouldInjectForceInstruction // v2.1: Pass force recommendation flag
    )

    // v2.1: CRITICAL - Loop Detection and Response Validation
    // Check if response is a loop (only if we should check)
    let loopDetection: LoopDetectionResult = { isLoop: false, suggestedAction: 'allow-response' }
    let hasRetriedForLoop = false

    if (shouldCheckForLoop(request.conversationHistory)) {
      loopDetection = detectLoop(aiResponse, sessionContext, clarificationCount)
      console.log(formatLoopDetection(loopDetection))

      // If loop detected, retry with force instruction
      if (loopDetection.isLoop && loopDetection.suggestedAction === 'retry-with-force') {
        console.log('[AI Chat] 🔁 RETRYING with force instruction due to loop detection')

        // Generate force instruction based on loop type
        const retryForceInstruction = generateForceInstruction(loopDetection.loopType, clarificationCount)

        // Append force instruction to enhanced prompt
        const retryPrompt = `${enhancedPrompt}\n\n${retryForceInstruction}`

        // Retry API call with force instruction
        aiResponse = await callOpenRouter(
          retryPrompt,
          request.conversationHistory,
          sessionContext,
          true // Force recommendation mode on retry
        )

        hasRetriedForLoop = true
        console.log('[AI Chat] ✅ Retry complete')
      }
    }

    // v2.1/v2.2: Response validation with retry on template violation (phase-aware for Step 4)
    const validation = validateResponseWithPhase(aiResponse, isFollowUpPhase)
    console.log(formatValidationErrors(validation))

    // v2.1: CRITICAL - Retry if template validation fails (max 1 retry)
    if (!validation.isValid && !hasRetriedForLoop) {
      // Only retry if we haven't already retried for loop detection
      console.warn('[AI Chat] 🔁 RETRYING due to template validation failure')

      // Generate correction instruction
      const expectedTemplate = categoryDetection.category === 'CLOTHS' ? 'A' : 'B'
      const correctionInstruction = `[CRITICAL CORRECTION - TEMPLATE VIOLATION DETECTED]

Your previous response did not follow Template ${expectedTemplate} requirements.

ERRORS DETECTED:
${validation.errors.join('\n')}

You MUST regenerate your response following Template ${expectedTemplate} structure EXACTLY:
${getTemplateInstruction(categoryDetection.category)}

MANDATORY: Fix all errors listed above and provide a complete ${expectedTemplate === 'A' ? 'outfit recommendation with products, prices, and links' : 'tips-based response without prices or links'}.`

      // Retry with correction instruction
      const correctionPrompt = `${enhancedPrompt}\n\n${correctionInstruction}`

      try {
        aiResponse = await callOpenRouter(
          correctionPrompt,
          request.conversationHistory,
          sessionContext,
          true // Force recommendation mode
        )

        // Validate retry response
        const retryValidation = validateResponseStructure(aiResponse)
        if (retryValidation.isValid) {
          console.log(`[AI Chat] ✅ Retry successful - Response validated (Template ${retryValidation.detectedTemplate})`)
        } else {
          console.warn('[AI Chat] ⚠️ Retry still has validation issues, but continuing')
          console.warn(formatValidationErrors(retryValidation))
        }
      } catch (retryError) {
        console.error('[AI Chat] Retry failed:', retryError)
        console.warn('[AI Chat] Using original response despite validation failure')
      }
    } else if (validation.isValid) {
      console.log(`[AI Chat] ✅ Response validated successfully (Template ${validation.detectedTemplate})`)
    }

    // Products to recommend (top 6)
    const recommendedProducts = filteredProducts.slice(0, 6)

    // KB003: Calculate cost-per-wear for recommended products
    if (recommendedProducts.length > 0) {
      const avgCostPerWear = calculateOutfitCostPerWear(recommendedProducts)
      const cpwTier = getOutfitCostPerWearTier(recommendedProducts)
      console.log(`[AI Chat] KB003: Cost-per-wear: ฿${avgCostPerWear.toFixed(0)}/wear (${cpwTier} tier)`)

      // Get trending hashtags for social proof context
      const hashtags = getOutfitHashtags(recommendedProducts)
      if (hashtags.length > 0) {
        console.log(`[AI Chat] KB003: Trending hashtags: ${hashtags.slice(0, 5).join(', ')}`)
      }
    }

    // Update session context with newly recommended products
    const newProductIds = extractProductIds(recommendedProducts)
    const updatedSessionContext = updateSessionContext(sessionContext, newProductIds)

    console.log(`[AI Chat] Recommended ${newProductIds.length} new products. Total in session: ${updatedSessionContext.recommendedProductIds.length}`)

    // Parse AI response to extract product recommendations
    // For now, we'll return the filtered products
    // In a more advanced version, we'd parse the AI response to extract specific SKUs

    // Generate outfit description for auto-image generation
    const distinctProducts = recommendedProducts.slice(0, 3); // Use top 3 distinct products for description
    const productNames = distinctProducts.map(p => p.name.en || p.name.th || 'Fashion Item').join(', ');
    const autoOutfitDescription = `Full body look for ${occasion || 'daily wear'}: ${productNames}. Context: ${occasion} setting.`;

    return {
      message: aiResponse,
      recommendedProducts,
      occasion,
      reasoning: `Found ${filteredProducts.length} unique products matching your request`,
      sessionContext: updatedSessionContext,
      // v3.2: Auto-trigger image generation if products are recommended
      imageRequest: recommendedProducts.length > 0,
      outfitDescription: autoOutfitDescription,
    }
  } catch (error) {
    console.error('AI Chat Service Error:', error)

    // Fallback logic also needs to trigger image?
    const fallbackResponse = getFallbackRecommendations(request, availableProducts)
    const detectedOccasion = detectOccasion(request.message)

    return {
      ...fallbackResponse,
      sessionContext: request.sessionContext,
      // Fallback auto-image
      imageRequest: fallbackResponse.recommendedProducts && fallbackResponse.recommendedProducts.length > 0,
      outfitDescription: `Fashion outfit for ${detectedOccasion || 'general wear'}`,
    }
  }
}

/**
 * Fallback recommendations when AI is unavailable
 */
export function getFallbackRecommendations(
  request: ChatRequest,
  availableProducts: EnhancedProduct[]
): ChatResponse {
  const occasion = detectOccasion(request.message)
  const filteredProducts = filterProductsForRequest(availableProducts, request, occasion)

  let message = 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ:\n\n'

  if (occasion) {
    const occasionNames: Record<OccasionType, string> = {
      work: 'การทำงาน/ออฟฟิศ',
      chill: 'วันชิลล์/วันหยุด',
      wedding: 'งานแต่งงาน',
      sport: 'การออกกำลังกาย',
      travel: 'การท่องเที่ยว',
      date: 'เดท',
      dinner: 'ดินเนอร์',
      cafe: 'ไปคาเฟ่',
      party: 'งานปาร์ตี้',
    }

    message += `สำหรับโอกาส: ${occasionNames[occasion]}\n\n`
  }

  message += `เราพบสินค้าที่เหมาะสมกับคุณ ${filteredProducts.length} รายการ`

  return {
    message,
    recommendedProducts: filteredProducts.slice(0, 6),
    occasion,
  }
}

/**
 * Chat API Route
 * Handles AI-powered fashion recommendations
 */

import { NextRequest, NextResponse } from 'next/server'
import type { EnhancedProduct } from '@/lib/types/product-types'
import type { UserProfile } from '@/lib/types/user-profile-types'
import { loadProductsServerSide, loadProductsFromSupabase } from '@/lib/server-product-loader'
import { transformDbProductsToEnhanced } from '@/lib/transformers/db-product-to-enhanced'
import {
  processAIChatRequest,
  getFallbackRecommendations,
  type ChatRequest,
} from '@/lib/services/ai-chat-service'
import { generateOutfitsFromQuery } from '@/lib/enhanced-outfit-generator'
import { getProductName, getProductPrice, getProductImageUrl } from '@/lib/utils/product-utils'
import { VersionUtils } from '@/lib/prompts/prompt-version'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { message, userPreferences, conversationHistory, sessionContext, conversationId } = body

    if (!message || typeof message !== 'string') {
      return NextResponse.json({ error: 'Message is required' }, { status: 400 })
    }

    console.log('[Chat API] Processing message:', message)

    // Log session context if provided (v2.0 feature)
    if (sessionContext) {
      console.log(`[Chat API] Session has ${sessionContext.recommendedProductIds?.length || 0} previously recommended products`)
    }

    // Load enhanced products - prefer Supabase, fallback to JSON files
    let products: EnhancedProduct[] = []

    if (process.env.SUPABASE_PRODUCTS_ENABLED === 'true') {
      const dbProducts = await loadProductsFromSupabase(undefined, 200)
      if (dbProducts && dbProducts.length > 0) {
        products = transformDbProductsToEnhanced(dbProducts)
        console.log(`[Chat API] Using Supabase products (${products.length} items)`)
      }
    }

    if (products.length === 0) {
      products = await loadProductsServerSide()
      console.log(`[Chat API] Using JSON products (${products.length} items)`)
    }

    if (products.length === 0) {
      console.warn('[Chat API] No enhanced products available, falling back to mock data')
    }

    console.log(`[Chat API] Using ${products.length} enhanced products`)

    // Check if AI is enabled AND products are available
    const useAI = process.env.OPENROUTER_API_KEY !== undefined && products.length > 0

    let response

    if (useAI) {
      // Use AI-powered recommendations
      console.log('[Chat API] Using AI-powered recommendations')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        conversationHistory,
        sessionContext, // v2.0: Include session context for duplicate prevention
        conversationId, // v2.0: Include conversation ID for session tracking
      }

      response = await processAIChatRequest(chatRequest, products)
    } else {
      // Use rule-based fallback
      console.log('[Chat API] Using rule-based recommendations (no AI key)')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        sessionContext, // v2.0: Include session context even for fallback
        conversationId, // v2.0: Include conversation ID
      }

      const fallbackResponse = getFallbackRecommendations(chatRequest, products)

      // Ensure imageRequest is set for flat-lay generation even in fallback mode
      response = {
        ...fallbackResponse,
        imageRequest: (fallbackResponse.recommendedProducts?.length ?? 0) > 0,
        outfitDescription: `Fashion outfit for ${fallbackResponse.occasion || 'general wear'}`,
      }
    }

    // v5.0: When v5 is active, return structured looks directly (no generateOutfitsFromQuery)
    if (VersionUtils.isV5Active() && response.looks) {
      console.log(`[Chat API v5] Returning ${response.looks.length} looks`)

      return NextResponse.json({
        message: response.message,
        looks: response.looks.map(look => ({
          lookNumber: look.lookNumber,
          styleName: look.styleName,
          items: look.items.map(item => ({
            name: item.name,
            brand: item.brand,
            category: item.category,
            color: item.color,
            description: item.description,
            sku: item.sku,
            price: item.price,
            url: item.url,
          })),
          tip: look.tip,
          totalPrice: look.totalPrice,
          imageStatus: look.imageStatus || 'pending',
        })),
        outfits: [], // Empty for backward compatibility
        occasion: response.occasion,
        reasoning: response.reasoning,
        sessionContext: response.sessionContext,
        imageRequest: response.imageRequest,
        outfitDescription: response.outfitDescription,
      })
    }

    // v4 and below: Legacy outfit generation
    // Convert userPreferences to UserProfile if available
    const userProfile: UserProfile | null = userPreferences ? {
      userName: userPreferences.userName || '',
      gender: 'women', // Currently fixed to women
      ageRange: userPreferences.ageRange || '20-29',
      stylePreferences: userPreferences.stylePreferences || [],
      userPhoto: userPreferences.userPhoto,
      fittingModelUrl: userPreferences.fittingModelUrl,
      onboardingCompleted: userPreferences.onboardingCompleted || false,
      createdAt: userPreferences.createdAt || new Date().toISOString(),
    } : null

    // Generate outfits from recommended products with user profile
    const outfits = generateOutfitsFromQuery(
      response.recommendedProducts || products,
      message,
      5,
      userProfile
    )

    console.log(`[Chat API] Generated ${outfits.length} outfits`)
    console.log(`[Chat API] imageRequest: ${response.imageRequest}, outfitDescription: ${response.outfitDescription ? 'yes' : 'no'}`)

    // Convert outfits to response format
    const outfitResponses = outfits.map((outfit) => ({
      id: outfit.id,
      title: outfit.title,
      description: outfit.description,
      totalPrice: outfit.totalPrice,
      items: outfit.products.map((product) => ({
        sku: product.sku,
        id: product.id,
        name: getProductName(product, 'th'),
        nameEn: getProductName(product, 'en'),
        brand: product.brand,
        price: getProductPrice(product),
        imageUrl: getProductImageUrl(product),
        onlineUrl: product.centralIntegration?.productUrl || '',
        category: product.classification?.category?.category || '',
        gender: product.classification?.gender || 'unisex',
        occasion: product.classification?.tags?.occasion || [],
        formality: product.style?.formalityLevel || 5,
        colors: [
          product.style?.colors?.primary || 'unknown',
          ...(product.style?.colors?.secondary || []),
        ].filter(Boolean),
        sizes: product.sizing?.availableSizes || [],
        availability: product.availability?.status || 'unknown',
      })),
      occasion: outfit.occasion,
      formality: outfit.formality,
      imageUrl: outfit.primaryImage,
    }))

    return NextResponse.json({
      message: response.message,
      outfits: outfitResponses,
      occasion: response.occasion,
      reasoning: response.reasoning,
      sessionContext: response.sessionContext, // v2.0: Return updated session context to client
      imageRequest: response.imageRequest, // Image generation flag
      outfitDescription: response.outfitDescription, // Outfit description for image generation
    })
  } catch (error) {
    console.error('[Chat API] Error:', error)
    return NextResponse.json(
      {
        error: 'Failed to process chat request',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

/**
 * Looks Parser for v5 Chat Flow
 * Parses AI responses containing ---LOOKS_DATA--- structured blocks
 *
 * @version 5.0.0
 */

import type { EnhancedProduct } from '../types/product-types';
import type { ChatLook, ChatLookItem, ParsedLooksResponse } from '../types/chat-types';

const LOOKS_START_MARKER = '---LOOKS_DATA---';
const LOOKS_END_MARKER = '---END_LOOKS_DATA---';

/**
 * Parse AI response to extract conversational text and structured looks data.
 *
 * Expected format in the AI response:
 * ```
 * [conversational Thai text...]
 *
 * ---LOOKS_DATA---
 * LOOK:1|Style Name Here
 * ITEM:Product Name|Category|Color|Description|SKU123|1290|https://central.co.th/...
 * ITEM:Another Product|Category|Color|Description|SKU456|2590|https://central.co.th/...
 * TIP:Styling tip for this look
 * TOTAL:3880
 * LOOK:2|Another Style
 * ITEM:...
 * TIP:...
 * TOTAL:...
 * ---END_LOOKS_DATA---
 * ```
 *
 * Graceful fallback: if no markers found, returns { text: fullResponse, looks: [] }
 */
export function parseLooksData(fullResponse: string): ParsedLooksResponse {
  if (!fullResponse || typeof fullResponse !== 'string') {
    return { text: '', looks: [] };
  }

  const startIdx = fullResponse.indexOf(LOOKS_START_MARKER);
  const endIdx = fullResponse.indexOf(LOOKS_END_MARKER);

  // Graceful fallback: no structured block found
  if (startIdx === -1) {
    // Try fallback markdown parser for inline product recommendations
    if (hasInlineProductPatterns(fullResponse)) {
      return parseFallbackMarkdown(fullResponse);
    }
    return { text: fullResponse.trim(), looks: [] };
  }

  // Extract conversational text (before the marker)
  const text = fullResponse.substring(0, startIdx).trim();

  // Extract the structured block
  const blockEnd = endIdx !== -1 ? endIdx : fullResponse.length;
  const block = fullResponse.substring(startIdx + LOOKS_START_MARKER.length, blockEnd).trim();

  if (!block) {
    return { text, looks: [] };
  }

  const looks: ChatLook[] = [];
  let currentLook: ChatLook | null = null;

  const lines = block.split('\n').map(l => l.trim()).filter(l => l.length > 0);

  for (const line of lines) {
    if (line.startsWith('LOOK:')) {
      // Save previous look if exists
      if (currentLook) {
        looks.push(currentLook);
      }

      const lookData = line.substring(5); // Remove 'LOOK:'
      const pipeIdx = lookData.indexOf('|');

      let lookNumber = looks.length + 1;
      let styleName = 'Look';

      if (pipeIdx !== -1) {
        const numStr = lookData.substring(0, pipeIdx).trim();
        const parsed = parseInt(numStr, 10);
        if (!isNaN(parsed)) lookNumber = parsed;
        styleName = lookData.substring(pipeIdx + 1).trim() || 'Look';
      } else {
        // No pipe, try to parse as just a number
        const parsed = parseInt(lookData.trim(), 10);
        if (!isNaN(parsed)) lookNumber = parsed;
      }

      currentLook = {
        lookNumber,
        styleName,
        items: [],
        totalPrice: 0,
        imageStatus: 'pending',
      };
    } else if (line.startsWith('ITEM:') && currentLook) {
      const itemData = line.substring(5); // Remove 'ITEM:'
      const parts = itemData.split('|');

      // Expected: Name|Category|Color|Description|SKU|Price|URL
      if (parts.length >= 7) {
        const price = parseFloat(parts[5].trim().replace(/,/g, ''));
        const item: ChatLookItem = {
          name: parts[0].trim(),
          brand: '', // Populated during catalog validation
          category: parts[1].trim(),
          color: parts[2].trim(),
          description: parts[3].trim(),
          sku: parts[4].trim(),
          price: isNaN(price) ? 0 : price,
          url: parts[6].trim(),
        };
        currentLook.items.push(item);
      } else if (parts.length >= 3) {
        // Partial data — try best effort
        const item: ChatLookItem = {
          name: parts[0]?.trim() || 'Unknown',
          brand: '', // Populated during catalog validation
          category: parts[1]?.trim() || 'Unknown',
          color: parts[2]?.trim() || 'Unknown',
          description: parts[3]?.trim() || '',
          sku: parts[4]?.trim() || '',
          price: parseFloat((parts[5] || '0').trim().replace(/,/g, '')) || 0,
          url: parts[6]?.trim() || '',
        };
        currentLook.items.push(item);
      }
      // Lines with fewer than 3 parts are silently skipped (malformed)
    } else if (line.startsWith('TIP:') && currentLook) {
      currentLook.tip = line.substring(4).trim();
    } else if (line.startsWith('TOTAL:') && currentLook) {
      const totalStr = line.substring(6).trim().replace(/,/g, '');
      const total = parseFloat(totalStr);
      if (!isNaN(total)) {
        currentLook.totalPrice = total;
      }
    }
    // Unknown lines are silently ignored
  }

  // Don't forget the last look
  if (currentLook) {
    // If TOTAL wasn't provided, calculate from items
    if (currentLook.totalPrice === 0 && currentLook.items.length > 0) {
      currentLook.totalPrice = currentLook.items.reduce((sum, item) => sum + item.price, 0);
    }
    looks.push(currentLook);
  }

  return { text, looks };
}

// ============================================================================
// Fallback Markdown Parser
// ============================================================================

/**
 * Detect if text contains inline product recommendation patterns.
 * Looks for numbered items with price + link indicators.
 */
function hasInlineProductPatterns(text: string): boolean {
  // Match patterns like: **1. Product Name** with price (บาท) and URL
  const numberedItemWithPrice = /\*\*\d+\.\s*.+?\*\*[\s\S]*?(?:฿|บาท|THB|\d{3,})/;
  const hasUrl = /https?:\/\/[^\s)]+/;
  return numberedItemWithPrice.test(text) && hasUrl.test(text);
}

/**
 * Parse inline markdown product recommendations as a fallback
 * when AI doesn't use the structured ---LOOKS_DATA--- format.
 *
 * Handles patterns like:
 *   **1. Product Name** - **Brand:** GIORDANO - **Price:** 🏷 420 บาท - **Link:** 🔗 https://...
 *   **1. Product Name** (Brand) - ราคา 420 บาท [link](url)
 */
function parseFallbackMarkdown(text: string): ParsedLooksResponse {
  const lines = text.split('\n');

  // Regex to match numbered product entries: **N. ...** or N. **...**
  const numberedItemRegex = /^\s*\*?\*?\s*(\d+)\.\s*\*{0,2}(.+?)\*{0,2}\s*[-–—]/;

  // Find the first numbered item to split intro text from product listing
  let firstItemLineIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (numberedItemRegex.test(lines[i]) || /^\s*\*{0,2}\s*\d+\.\s/.test(lines[i])) {
      firstItemLineIdx = i;
      break;
    }
  }

  // Check for "Look N:" headers to detect multi-look grouping
  const lookHeaderRegex = /(?:look|ลุค)\s*(\d+)\s*[:\-–—|]/i;

  const conversationalText = firstItemLineIdx > 0
    ? lines.slice(0, firstItemLineIdx).join('\n').trim()
    : '';

  const productSection = firstItemLineIdx >= 0
    ? lines.slice(firstItemLineIdx).join('\n')
    : text;

  // Extract individual product entries
  // Each entry starts with a numbered pattern like **N.
  const productEntryRegex = /\*{0,2}\s*(\d+)\.\s*\*{0,2}\s*(.+?)(?=\n\s*\*{0,2}\s*\d+\.\s|\n\s*(?:look|ลุค)\s*\d+|$)/gis;

  interface ExtractedItem {
    name: string;
    brand: string;
    price: number;
    url: string;
    lookGroup: number;
  }

  const extractedItems: ExtractedItem[] = [];
  let currentLookGroup = 1;

  // Process line by line for better control
  const productLines = productSection.split('\n');
  let currentEntry = '';
  let currentNumber = 0;

  for (const line of productLines) {
    // Check for look headers
    const lookMatch = line.match(lookHeaderRegex);
    if (lookMatch) {
      currentLookGroup = parseInt(lookMatch[1], 10);
      continue;
    }

    // Check if this line starts a new numbered entry
    const numMatch = line.match(/^\s*\*{0,2}\s*(\d+)\.\s/);
    if (numMatch) {
      // Process previous entry if exists
      if (currentEntry && currentNumber > 0) {
        const item = extractProductFromEntry(currentEntry);
        if (item) {
          extractedItems.push({ ...item, lookGroup: currentLookGroup });
        }
      }
      currentNumber = parseInt(numMatch[1], 10);
      currentEntry = line;
    } else if (currentEntry) {
      // Continuation of current entry
      currentEntry += '\n' + line;
    }
  }

  // Process last entry
  if (currentEntry && currentNumber > 0) {
    const item = extractProductFromEntry(currentEntry);
    if (item) {
      extractedItems.push({ ...item, lookGroup: currentLookGroup });
    }
  }

  if (extractedItems.length === 0) {
    return { text: text.trim(), looks: [] };
  }

  // Group items into looks
  const lookGroups = new Map<number, ExtractedItem[]>();
  for (const item of extractedItems) {
    const group = lookGroups.get(item.lookGroup) || [];
    group.push(item);
    lookGroups.set(item.lookGroup, group);
  }

  // If only one group and many items, split into looks of ~3 items each
  const looks: ChatLook[] = [];
  if (lookGroups.size === 1 && extractedItems.length > 4) {
    const items = extractedItems;
    const itemsPerLook = 3;
    for (let i = 0; i < items.length; i += itemsPerLook) {
      const chunk = items.slice(i, i + itemsPerLook);
      const lookNumber = looks.length + 1;
      looks.push({
        lookNumber,
        styleName: `Look ${lookNumber}`,
        items: chunk.map(item => ({
          name: item.name,
          brand: item.brand,
          category: 'Unknown',
          color: 'Unknown',
          description: '',
          sku: '',
          price: item.price,
          url: item.url,
        })),
        totalPrice: chunk.reduce((sum, item) => sum + item.price, 0),
        imageStatus: 'pending',
      });
    }
  } else {
    // Use detected look groups (or single group)
    for (const [groupNum, items] of lookGroups) {
      looks.push({
        lookNumber: groupNum,
        styleName: `Look ${groupNum}`,
        items: items.map(item => ({
          name: item.name,
          brand: item.brand,
          category: 'Unknown',
          color: 'Unknown',
          description: '',
          sku: '',
          price: item.price,
          url: item.url,
        })),
        totalPrice: items.reduce((sum, item) => sum + item.price, 0),
        imageStatus: 'pending',
      });
    }
  }

  // Clean markdown artifacts from conversational text
  const cleanText = cleanMarkdownText(conversationalText);

  return { text: cleanText, looks };
}

/**
 * Extract product details (name, brand, price, url) from a single markdown entry.
 */
function extractProductFromEntry(entry: string): { name: string; brand: string; price: number; url: string } | null {
  // Extract product name from **N. Product Name** or similar
  const nameMatch = entry.match(/\*{0,2}\s*\d+\.\s*\*{0,2}\s*(.+?)\*{0,2}\s*(?:[-–—]|\n|$)/);
  const name = nameMatch ? nameMatch[1].trim().replace(/\*+/g, '').trim() : '';

  if (!name) return null;

  // Extract brand: **Brand:** X or (Brand) or Brand: X
  let brand = '';
  const brandPatterns = [
    /\*{0,2}(?:Brand|แบรนด์|ยี่ห้อ)\s*[:\uff1a]\*{0,2}\s*(.+?)(?:\s*[-–—]|\s*\n|$)/i,
    /\(([A-Za-z][A-Za-z\s&.]+)\)/,
  ];
  for (const pattern of brandPatterns) {
    const match = entry.match(pattern);
    if (match) {
      brand = match[1].trim().replace(/\*+/g, '').trim();
      break;
    }
  }

  // Extract price: 420 บาท, ฿420, THB 420, 🏷 420, ราคา 420
  let price = 0;
  const pricePatterns = [
    /(?:Price|ราคา|🏷️?)\s*[:\uff1a]?\s*\*{0,2}\s*🏷?\s*([0-9,]+(?:\.\d+)?)\s*(?:บาท|THB|฿)/i,
    /(?:฿|THB)\s*([0-9,]+(?:\.\d+)?)/i,
    /([0-9,]+(?:\.\d+)?)\s*(?:บาท|THB|฿)/,
    /(?:Price|ราคา|🏷️?)\s*[:\uff1a]?\s*\*{0,2}\s*🏷?\s*([0-9,]+(?:\.\d+)?)/i,
  ];
  for (const pattern of pricePatterns) {
    const match = entry.match(pattern);
    if (match) {
      price = parseFloat(match[1].replace(/,/g, ''));
      if (!isNaN(price) && price > 0) break;
    }
  }

  // Extract URL
  let url = '';
  const urlPatterns = [
    /(?:Link|ลิงก์|🔗)\s*[:\uff1a]?\s*🔗?\s*(https?:\/\/[^\s)>\]]+)/i,
    /\[.+?\]\((https?:\/\/[^\s)]+)\)/,
    /(https?:\/\/[^\s)>\]]+)/,
  ];
  for (const pattern of urlPatterns) {
    const match = entry.match(pattern);
    if (match) {
      url = match[1].trim();
      break;
    }
  }

  // Must have at least name and (price or url) to be considered a product
  if (!name || (price === 0 && !url)) return null;

  return { name, brand, price, url };
}

/**
 * Clean markdown formatting artifacts from conversational text.
 * Removes bold markers, emoji artifacts, etc.
 */
function cleanMarkdownText(text: string): string {
  return text
    .replace(/\*{2,}(.+?)\*{2,}/g, '$1')  // **bold** → bold
    .replace(/\*(.+?)\*/g, '$1')           // *italic* → italic
    .replace(/#{1,6}\s*/g, '')              // ## headers → remove
    .trim();
}

/**
 * Validate looks against the product catalog.
 * - Matches each item's SKU against the catalog
 * - Forces catalog URLs (never trust AI-fabricated URLs)
 * - Drops items with SKUs not found in the catalog
 * - Returns validated looks (may have fewer items than original)
 */
export function validateLooksAgainstCatalog(
  looks: ChatLook[],
  catalog: EnhancedProduct[]
): ChatLook[] {
  if (!looks.length || !catalog.length) return looks;

  // Build SKU lookup map
  const skuMap = new Map<string, EnhancedProduct>();
  for (const product of catalog) {
    if (product.sku) {
      skuMap.set(product.sku.toLowerCase(), product);
    }
    // Also index by centralSKU if different
    if (product.centralIntegration?.centralSKU) {
      skuMap.set(product.centralIntegration.centralSKU.toLowerCase(), product);
    }
  }

  // Build URL lookup map (for fallback parser items that have URLs but no SKUs)
  const urlMap = new Map<string, EnhancedProduct>();
  for (const product of catalog) {
    const productUrl = product.centralIntegration?.productUrl;
    if (productUrl) {
      urlMap.set(normalizeUrl(productUrl), product);
    }
  }

  return looks.map(look => {
    const validatedItems = look.items
      .map(item => {
        let catalogProduct: EnhancedProduct | undefined;

        // Primary: SKU-based lookup
        if (item.sku) {
          catalogProduct = skuMap.get(item.sku.toLowerCase());
        }

        // Secondary: URL-based lookup (for fallback-parsed items without SKUs)
        if (!catalogProduct && item.url) {
          catalogProduct = urlMap.get(normalizeUrl(item.url));
        }

        if (!catalogProduct) return null; // Not in catalog = drop

        // Force catalog URL and price, populate SKU if missing
        return {
          ...item,
          url: catalogProduct.centralIntegration?.productUrl || item.url,
          price: catalogProduct.pricing?.currentPrice || item.price,
          name: item.name, // Keep AI's display name (may be Thai)
          brand: catalogProduct.brand || item.brand,
          sku: item.sku || catalogProduct.sku || catalogProduct.centralIntegration?.centralSKU || '',
        };
      })
      .filter((item): item is ChatLookItem => item !== null);

    // Recalculate total from validated items
    const totalPrice = validatedItems.reduce((sum, item) => sum + item.price, 0);

    return {
      ...look,
      items: validatedItems,
      totalPrice,
    };
  }).filter(look => look.items.length > 0); // Drop looks with no valid items
}

/**
 * Normalize a URL for comparison (remove trailing slashes, query params, lowercase).
 */
function normalizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    // Keep host + pathname, lowercase, strip trailing slash
    return (parsed.host + parsed.pathname).toLowerCase().replace(/\/+$/, '');
  } catch {
    // If URL parsing fails, do basic normalization
    return url.toLowerCase().replace(/\/+$/, '').replace(/^https?:\/\//, '');
  }
}

