  });

  it('should support rollback to v4.0 via env', () => {
    process.env.SYSTEM_PROMPT_VERSION = 'v4.0';
    expect(getPromptVersionFromEnv()).toBe('v4.0');
    expect(VersionUtils.isV5Active()).toBe(false);
